SELECT EXISTS (
    SELECT 1
    FROM test_result
    WHERE sample_id = #{sampleId}
      AND parameter_id = #{parameterId}
      AND status IN ('PENDING', 'APPROVED'))

mapper.update:
UPDATE test_result
SET status = #{toStatus}, reviewed_by = #{actor}, reviewed_at = #{reviewedAt},
    reject_reason = #{rejectReason,jdbcType=VARCHAR}
WHERE id = #{resultId}
  AND sample_id = #{sampleId}
  AND status = 'PENDING'
